82		if err != nil {
83			return err
84		}
85		if message == nil {
86			return nil
87		}
88		message.ReplyTo = emailSetting.ReplyTo
89	
90		config := EmailConfigFromInstanceSetting(emailSetting)
91		if err := config.Validate(); err != nil {
92			return errors.Wrap(err, "invalid notification email setting")
93		}
94	
95		d.sender(config, message)
96		return nil
97	}
