148	func (d *EmailDispatcher) buildMemoCommentEmailMessage(message *storepb.InboxMessage, receiver *store.User, senderName string, memosByID map[int32]*store.Memo) (*email.Message, error) {
149		payload := message.GetMemoComment()
150		if payload == nil {
151			return nil, nil
152		}
153		commentMemo := memosByID[payload.MemoId]
154		relatedMemo := memosByID[payload.RelatedMemoId]
155		if !canViewerAccessMemo(receiver, commentMemo) || !canViewerAccessMemo(receiver, relatedMemo) {
156			return nil, nil
157		}
158		url := d.memoCommentURL(relatedMemo, commentMemo)
159		if url == "" {
160			return nil, nil
161		}
162	
163		body := []string{
164			fmt.Sprintf("Hi %s,", displayNameForEmail(receiver)),
165			"",
166			fmt.Sprintf("%s commented on your memo.", senderName),
167			"",
168			"Open in Memos:",
169			url,
170			"",
171			"You are receiving this because you own this memo.",
172		}
173	
174		return &email.Message{
175			To:      []string{receiver.Email},
176			Subject: fmt.Sprintf("[Memos] %s commented on your memo", senderName),
177			Body:    strings.Join(body, "\n"),
178		}, nil
179	}
180	
181	func (d *EmailDispatcher) buildMemoMentionEmailMessage(message *storepb.InboxMessage, receiver *store.User, senderName string, memosByID map[int32]*store.Memo) (*email.Message, error) {
182		payload := message.GetMemoMention()
183		if payload == nil {
184			return nil, nil
185		}
186		memo := memosByID[payload.MemoId]
187		if !canViewerAccessMemo(receiver, memo) {
188			return nil, nil
189		}
190		url := d.memoURL(memo)
191		if url == "" {
192			return nil, nil
193		}
194	
195		body := []string{
196			fmt.Sprintf("Hi %s,", displayNameForEmail(receiver)),
197			"",
198			fmt.Sprintf("%s mentioned you in a memo.", senderName),
199			"",
200			"Open in Memos:",
201			url,
202			"",
203			"You are receiving this because you were mentioned in this memo.",
204		}
205	
206		return &email.Message{
207			To:      []string{receiver.Email},
208			Subject: fmt.Sprintf("[Memos] %s mentioned you in a memo", senderName),
209			Body:    strings.Join(body, "\n"),
210		}, nil
211	}
