150		baseURL := c.Scheme() + "://" + c.Request().Host
151		rss, lastModified, err := s.generateRSSFromMemoList(ctx, memoList, baseURL, user)
152		if err != nil {
153			return echo.NewHTTPError(http.StatusInternalServerError, "Failed to generate rss").Wrap(err)
154		}
155	
156		// Cache the result
157		etag := s.putInCache(cacheKey, rss, lastModified)
158		s.setRSSHeaders(c, etag, lastModified)
159		return c.String(http.StatusOK, rss)
160	}
